slug = env['ir.config_parameter'].sudo().get_param('ppx.tenant_slug', '') host = env['ir.config_parameter'].sudo().get_param('ppx.portal_host', 'paymentportalexpress.com') environment = env['ir.config_parameter'].sudo().get_param('ppx.environment', 'production')
if not slug: raise UserError( "Payment Portal Express is not configured yet.\n\n" "Settings > Payment Portal Express: fill in the account name from your " "portal's Accounts page." )
partner = records[:1] if not partner: raise UserError("Select a customer first.")
# Deliberately not filtered on payment status. The portal's own lookup does not # require the invoice to still be open, so any posted invoice works -- which # means the button still opens for a customer who has paid everything, landing # them on their receipts rather than an error. A button that dead-ends for # fully-paid customers is one people stop trusting. # # Newest first: most likely to have a token already, and most likely to survive # any pruning of old records. Scoped to the company being viewed, because Odoo # reuses invoice numbers across companies and keeps their ledgers apart. inv = env['account.move'].search([ ('partner_id', 'child_of', partner.id), ('move_type', '=', 'out_invoice'), ('state', '=', 'posted'), ('company_id', '=', env.company.id), ], order='id desc', limit=1)
if not inv: raise UserError("This customer has no posted invoices yet.")
token = inv._portal_ensure_token()
action = { 'type': 'ir.actions.act_url', 'url': 'https://%s/pay/odoo/%s?ref=%s&env=%s' % (host, slug, token, environment), 'target': 'new', }
